#!/bin/bash
sed -i '/<label className="block text-sm font-medium mb-1">{language === "bn" ? "তারিখ" : "Date"}<\/label>/i \ \ \ \ \ \ \ \ \ \ \ \ \ \ <div>\n\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ <label className="block text-sm font-medium mb-1">{language === "bn" ? "শাখার পত্র নং" : "Branch Letter No"}<\/label>\n\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ <input type="text" required value={sanctionData.letterNo || ""} onChange={e => setSanctionData({...sanctionData, letterNo: e.target.value})} className="w-full p-2.5 rounded-xl border dark:bg-slate-800" placeholder={language === "bn" ? "যেমন: প্রশা-০২/২০২৫-২০২৬/৯৭" : "e.g. Prash-02..."} \/>\n\ \ \ \ \ \ \ \ \ \ \ \ \ \ <\/div>\n\ \ \ \ \ \ \ \ \ \ \ \ \ \ <div>\n\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ <label className="block text-sm font-medium mb-1">{language === "bn" ? "শাখার পত্রের তারিখ" : "Branch Letter Date"}<\/label>\n\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ <input type="date" required value={sanctionData.letterDate || ""} onChange={e => setSanctionData({...sanctionData, letterDate: e.target.value})} className="w-full p-2.5 rounded-xl border dark:bg-slate-800" \/>\n\ \ \ \ \ \ \ \ \ \ \ \ \ \ <\/div>' src/components/PostFactoProposalsView.tsx
